// One scheduled weekly offering of a course.
class Section {
    private final String sectionId;   // unique id, e.g. SEC1
    private final String courseId;    // which course this offers
    private final String dayOfWeek;   // e.g. "MONDAY"
    private final int startHour;      // 24-hour clock start
    private final int endHour;        // 24-hour clock end
    private final int capacity;       // total seats

    public Section(String sectionId, String courseId, String dayOfWeek, int startHour, int endHour, int capacity) {
        this.sectionId = sectionId;   // store id
        this.courseId = courseId;     // store course
        this.dayOfWeek = dayOfWeek;   // store day
        this.startHour = startHour;   // store start hour
        this.endHour = endHour;       // store end hour
        this.capacity = capacity;     // store capacity
    }

    public String getSectionId() { return sectionId; }  // id getter
    public String getCourseId() { return courseId; }     // course getter
    public String getDayOfWeek() { return dayOfWeek; }   // day getter
    public int getStartHour() { return startHour; }      // start getter
    public int getEndHour() { return endHour; }          // end getter
    public int getCapacity() { return capacity; }        // capacity getter

    // True if this section's weekly slot overlaps another one.
    public boolean overlaps(Section other) {
        if (!this.dayOfWeek.equals(other.dayOfWeek)) return false; // different days never conflict
        return this.startHour < other.endHour && other.startHour < this.endHour; // strict interval overlap
    }
}

// Creates sections with sequential ids for a course.
class SectionFactory {
    private int counter = 0; // running id counter across all sections created

    public java.util.List<Section> createSections(String courseId, int count, int capacity,
                                                    String dayOfWeek, int startHour, int endHour) {
        java.util.List<Section> created = new java.util.ArrayList<>(); // result list
        for (int i = 0; i < count; i++) {                                // create 'count' sections
            counter++;                                                    // bump id counter
            created.add(new Section("SEC" + counter, courseId, dayOfWeek, startHour, endHour, capacity)); // e.g. SEC1
        }
        return created; // hand back the new sections
    }
}

