// Strategy interface: decides whether a student may enroll in a section.
interface EnrollmentEligibilityStrategy {
    // Returns null if eligible, or a rejection reason string if not.
    String checkEligibility(Student student, Course course, Section section, java.util.List<Section> currentSections);
}

// Checks prerequisite completion, then schedule conflicts against current sections.
class PrerequisiteAndScheduleEligibilityStrategy implements EnrollmentEligibilityStrategy {
    @Override
    public String checkEligibility(Student student, Course course, Section section, java.util.List<Section> currentSections) {
        String prereq = course.getPrerequisiteCourseId();               // this course's prerequisite, may be null
        if (prereq != null && !student.getCompletedCourses().contains(prereq)) {
            return "Prerequisite not completed: " + prereq;                // fails prerequisite check
        }
        for (Section existing : currentSections) {                        // check every currently-enrolled section
            if (existing.overlaps(section)) {                               // time slot overlaps
                return "Schedule conflict with section " + existing.getSectionId(); // fails schedule check
            }
        }
        return null; // eligible: no prerequisite issue, no schedule conflict
    }
}

