#include <vector>
using namespace std;

// Strategy interface: decides whether a student may enroll in a section.
class EnrollmentEligibilityStrategy {
public:
    // Returns empty string if eligible, or a rejection reason string if not.
    virtual string checkEligibility(const Student& student, const Course& course,
                                     const Section& section, const vector<Section>& currentSections) = 0;
    virtual ~EnrollmentEligibilityStrategy() {}
};

// Checks prerequisite completion, then schedule conflicts against current sections.
class PrerequisiteAndScheduleEligibilityStrategy : public EnrollmentEligibilityStrategy {
public:
    string checkEligibility(const Student& student, const Course& course,
                             const Section& section, const vector<Section>& currentSections) override {
        string prereq = course.prerequisiteCourseId;              // this course's prerequisite, may be empty
        if (!prereq.empty() && student.completedCourses.find(prereq) == student.completedCourses.end()) {
            return "Prerequisite not completed: " + prereq;         // fails prerequisite check
        }
        for (auto& existing : currentSections) {                    // check every currently-enrolled section
            if (existing.overlaps(section)) {                         // time slot overlaps
                return "Schedule conflict with section " + existing.sectionId; // fails schedule check
            }
        }
        return ""; // eligible: no prerequisite issue, no schedule conflict
    }
};

// A student and the courses they have already completed.
class Student {
public:
    string studentId;              // unique id
    string name;                    // display name
    set<string> completedCourses;  // finished course ids

    Student() {}
    Student(string id, string n) : studentId(id), name(n) {}
    // constructor stores id and name; completedCourses starts empty

    void markCompleted(string courseId) { completedCourses.insert(courseId); } // record a completed course
};

