// Observer interface: reacts to enrollment lifecycle events.
interface EnrollmentObserver {
    void onEnrollmentConfirmed(Enrollment enrollment);          // seat assigned
    void onEnrollmentRejected(String studentId, String reason);  // ineligible
    void onWaitlisted(Enrollment enrollment);                    // no seat, joined waitlist
    void onWaitlistPromoted(Enrollment enrollment);              // waitlisted enrollment got a seat
    void onEnrollmentDropped(Enrollment enrollment);             // enrollment dropped
}

// Simple observer that prints events to the console.
class ConsoleEnrollmentObserver implements EnrollmentObserver {
    @Override
    public void onEnrollmentConfirmed(Enrollment enrollment) {
        System.out.println("Enrollment " + enrollment.getEnrollmentId() + " confirmed for " + enrollment.getStudentId() + " in " + enrollment.getSectionId());
    }

    @Override
    public void onEnrollmentRejected(String studentId, String reason) {
        System.out.println("Enrollment rejected for " + studentId + ": " + reason);
    }

    @Override
    public void onWaitlisted(Enrollment enrollment) {
        System.out.println("Enrollment " + enrollment.getEnrollmentId() + " waitlisted for " + enrollment.getStudentId() + " in " + enrollment.getSectionId());
    }

    @Override
    public void onWaitlistPromoted(Enrollment enrollment) {
        System.out.println("Enrollment " + enrollment.getEnrollmentId() + " promoted for " + enrollment.getStudentId() + " in " + enrollment.getSectionId());
    }

    @Override
    public void onEnrollmentDropped(Enrollment enrollment) {
        System.out.println("Enrollment " + enrollment.getEnrollmentId() + " dropped for " + enrollment.getStudentId());
    }
}

// Custom exceptions for the realistic failure modes.
class EnrollmentNotEligibleException extends RuntimeException {
    public EnrollmentNotEligibleException(String msg) { super(msg); }
}
class SectionFullException extends RuntimeException {
    public SectionFullException(String msg) { super(msg); }
}
class InvalidEnrollmentException extends RuntimeException {
    public InvalidEnrollmentException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class CourseRegistrationService {
    private final java.util.Map<String, Course> courses = new java.util.HashMap<>();       // courseId -> Course
    private final java.util.Map<String, Section> sections = new java.util.HashMap<>();      // sectionId -> Section
    private final java.util.Map<String, Student> students = new java.util.HashMap<>();      // studentId -> Student
    private final java.util.Map<String, Enrollment> enrollments = new java.util.HashMap<>(); // enrollmentId -> Enrollment
    private final java.util.Map<String, java.util.List<Enrollment>> waitlists = new java.util.HashMap<>(); // sectionId -> FIFO queue
    private final EnrollmentEligibilityStrategy eligibilityStrategy; // pluggable eligibility rules
    private final java.util.List<EnrollmentObserver> observers = new java.util.ArrayList<>(); // listeners
    private int enrollmentCounter = 0; // simple id generator

    public CourseRegistrationService(EnrollmentEligibilityStrategy eligibilityStrategy) {
        this.eligibilityStrategy = eligibilityStrategy; // store chosen strategy
    }

    public void addCourse(Course course) { courses.put(course.getCourseId(), course); }         // register a course
    public void addSection(Section section) {
        sections.put(section.getSectionId(), section);                                            // register a section
        waitlists.put(section.getSectionId(), new java.util.ArrayList<>());                         // init its waitlist queue
    }
    public void addStudent(Student student) { students.put(student.getStudentId(), student); }   // register a student
    public void addObserver(EnrollmentObserver observer) { observers.add(observer); }              // register a listener
    public void markCourseCompleted(String studentId, String courseId) { students.get(studentId).markCompleted(courseId); } // record completion

    private java.util.List<Section> currentSectionsFor(String studentId) {
        java.util.List<Section> result = new java.util.ArrayList<>(); // sections this student is confirmed in
        for (Enrollment e : enrollments.values()) {                    // scan all enrollments
            if (e.getStudentId().equals(studentId) && "CONFIRMED".equals(e.getStatus())) {
                result.add(sections.get(e.getSectionId()));               // include this confirmed section
            }
        }
        return result; // hand back the student's current sections
    }

    private int confirmedCount(String sectionId) {
        int count = 0;                                                  // running total
        for (Enrollment e : enrollments.values()) {                      // scan all enrollments
            if (e.getSectionId().equals(sectionId) && "CONFIRMED".equals(e.getStatus())) count++; // count confirmed ones
        }
        return count; // total seats currently taken
    }

    // Enrolls a student in a section if eligible, assigning a seat or waitlisting.
    public synchronized Enrollment enroll(String studentId, String sectionId) {
        Student student = students.get(studentId);         // look up student
        Section section = sections.get(sectionId);          // look up section
        Course course = courses.get(section.getCourseId()); // look up course
        java.util.List<Section> currentSections = currentSectionsFor(studentId); // student's existing sections
        String reason = eligibilityStrategy.checkEligibility(student, course, section, currentSections); // eligibility check
        enrollmentCounter++;                                  // bump id counter
        String enrollmentId = "ENR-" + enrollmentCounter;      // build id
        if (reason != null) {                                  // not eligible
            for (EnrollmentObserver obs : observers) obs.onEnrollmentRejected(studentId, reason); // notify
            throw new EnrollmentNotEligibleException(reason);
        }
        Enrollment enrollment = new Enrollment(enrollmentId, studentId, sectionId); // build enrollment
        if (confirmedCount(sectionId) < section.getCapacity()) { // a seat is free
            enrollment.setStatus("CONFIRMED");                     // confirmed
            enrollments.put(enrollmentId, enrollment);              // store it
            for (EnrollmentObserver obs : observers) obs.onEnrollmentConfirmed(enrollment); // notify
            return enrollment; // hand back to caller
        }
        enrollment.setStatus("WAITLISTED");                       // waitlisted
        enrollments.put(enrollmentId, enrollment);                 // store it
        waitlists.get(sectionId).add(enrollment);                   // enqueue FIFO
        for (EnrollmentObserver obs : observers) obs.onWaitlisted(enrollment); // notify
        return enrollment; // hand back to caller
    }

    // Drops an enrollment; if it held a seat, promotes the next waitlisted student into it.
    public synchronized void dropEnrollment(String enrollmentId) {
        Enrollment enrollment = enrollments.get(enrollmentId); // look up enrollment
        if (enrollment == null || "DROPPED".equals(enrollment.getStatus())) {
            throw new InvalidEnrollmentException("Unknown or already-dropped enrollment: " + enrollmentId);
        }
        String sectionId = enrollment.getSectionId();            // section this enrollment held
        if ("WAITLISTED".equals(enrollment.getStatus())) {          // simple case: just dequeue
            waitlists.get(sectionId).remove(enrollment);              // remove from queue
            enrollment.setStatus("DROPPED");                            // mark dropped
            for (EnrollmentObserver obs : observers) obs.onEnrollmentDropped(enrollment); // notify
            return;
        }
        enrollment.setStatus("DROPPED");                            // mark dropped (frees a seat implicitly via confirmedCount)
        for (EnrollmentObserver obs : observers) obs.onEnrollmentDropped(enrollment); // notify
        java.util.List<Enrollment> queue = waitlists.get(sectionId); // this section's waitlist
        if (!queue.isEmpty()) {                                       // someone is waiting
            Enrollment promoted = queue.remove(0);                       // longest-waiting entry
            promoted.setStatus("CONFIRMED");                              // confirmed into the freed seat
            for (EnrollmentObserver obs : observers) obs.onWaitlistPromoted(promoted); // notify
        }
    }
}

