using namespace std;

// Observer interface: reacts to enrollment lifecycle events.
class EnrollmentObserver {
public:
    virtual void onEnrollmentConfirmed(const Enrollment& enrollment) = 0;
    virtual void onEnrollmentRejected(const string& studentId, const string& reason) = 0;
    virtual void onWaitlisted(const Enrollment& enrollment) = 0;
    virtual void onWaitlistPromoted(const Enrollment& enrollment) = 0;
    virtual void onEnrollmentDropped(const Enrollment& enrollment) = 0;
    virtual ~EnrollmentObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleEnrollmentObserver : public EnrollmentObserver {
public:
    void onEnrollmentConfirmed(const Enrollment& enrollment) override {
        cout << "Enrollment " << enrollment.enrollmentId << " confirmed for " << enrollment.studentId << " in " << enrollment.sectionId << endl;
    }
    void onEnrollmentRejected(const string& studentId, const string& reason) override {
        cout << "Enrollment rejected for " << studentId << ": " << reason << endl;
    }
    void onWaitlisted(const Enrollment& enrollment) override {
        cout << "Enrollment " << enrollment.enrollmentId << " waitlisted for " << enrollment.studentId << " in " << enrollment.sectionId << endl;
    }
    void onWaitlistPromoted(const Enrollment& enrollment) override {
        cout << "Enrollment " << enrollment.enrollmentId << " promoted for " << enrollment.studentId << " in " << enrollment.sectionId << endl;
    }
    void onEnrollmentDropped(const Enrollment& enrollment) override {
        cout << "Enrollment " << enrollment.enrollmentId << " dropped for " << enrollment.studentId << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class EnrollmentNotEligibleException : public runtime_error {
public: EnrollmentNotEligibleException(const string& msg) : runtime_error(msg) {}
};
class SectionFullException : public runtime_error {
public: SectionFullException(const string& msg) : runtime_error(msg) {}
};
class InvalidEnrollmentException : public runtime_error {
public: InvalidEnrollmentException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class CourseRegistrationService {
    map<string, Course> courses;                     // courseId -> Course
    map<string, Section> sections;                   // sectionId -> Section
    map<string, Student> students;                   // studentId -> Student
    map<string, Enrollment> enrollments;             // enrollmentId -> Enrollment
    map<string, vector<string>> waitlists;           // sectionId -> FIFO queue of enrollmentIds
    shared_ptr<EnrollmentEligibilityStrategy> eligibilityStrategy; // pluggable eligibility rules
    vector<shared_ptr<EnrollmentObserver>> observers; // listeners
    int enrollmentCounter = 0;                         // simple id generator

    vector<Section> currentSectionsFor(string studentId) {
        vector<Section> result;                          // sections this student is confirmed in
        for (auto& entry : enrollments) {                  // scan all enrollments
            if (entry.second.studentId == studentId && entry.second.status == "CONFIRMED") {
                result.push_back(sections.at(entry.second.sectionId)); // include this confirmed section
            }
        }
        return result; // hand back the student's current sections
    }

    int confirmedCount(string sectionId) {
        int count = 0;                                    // running total
        for (auto& entry : enrollments) {                    // scan all enrollments
            if (entry.second.sectionId == sectionId && entry.second.status == "CONFIRMED") count++; // count confirmed ones
        }
        return count; // total seats currently taken
    }

public:
    CourseRegistrationService(shared_ptr<EnrollmentEligibilityStrategy> strategy) : eligibilityStrategy(strategy) {}

    void addCourse(Course course) { courses.insert({course.courseId, course}); }           // register a course
    void addSection(Section section) {
        sections.insert({section.sectionId, section});                                       // register a section
        waitlists[section.sectionId] = {};                                                     // init its waitlist queue
    }
    void addStudent(Student student) { students.insert({student.studentId, student}); }    // register a student
    void addObserver(shared_ptr<EnrollmentObserver> observer) { observers.push_back(observer); } // register a listener
    void markCourseCompleted(string studentId, string courseId) { students.at(studentId).markCompleted(courseId); } // record completion

    Enrollment enroll(string studentId, string sectionId) {
        Student& student = students.at(studentId);           // look up student
        Section& section = sections.at(sectionId);             // look up section
        Course& course = courses.at(section.courseId);          // look up course
        vector<Section> current = currentSectionsFor(studentId); // student's existing sections
        string reason = eligibilityStrategy->checkEligibility(student, course, section, current); // eligibility check
        enrollmentCounter++;                                      // bump id counter
        string enrollmentId = "ENR-" + to_string(enrollmentCounter); // build id
        if (!reason.empty()) {                                     // not eligible
            for (auto& obs : observers) obs->onEnrollmentRejected(studentId, reason); // notify
            throw EnrollmentNotEligibleException(reason);
        }
        Enrollment enrollment(enrollmentId, studentId, sectionId);  // build enrollment
        if (confirmedCount(sectionId) < section.capacity) {          // a seat is free
            enrollment.status = "CONFIRMED";                           // confirmed
            enrollments.insert({enrollmentId, enrollment});              // store it
            for (auto& obs : observers) obs->onEnrollmentConfirmed(enrollment); // notify
            return enrollment; // hand back to caller
        }
        enrollment.status = "WAITLISTED";                            // waitlisted
        enrollments.insert({enrollmentId, enrollment});                // store it
        waitlists[sectionId].push_back(enrollmentId);                   // enqueue FIFO
        for (auto& obs : observers) obs->onWaitlisted(enrollment); // notify
        return enrollment; // hand back to caller
    }

    void dropEnrollment(string enrollmentId) {
        auto it = enrollments.find(enrollmentId); // look up enrollment
        if (it == enrollments.end() || it->second.status == "DROPPED") {
            throw InvalidEnrollmentException("Unknown or already-dropped enrollment: " + enrollmentId);
        }
        Enrollment& enrollment = it->second;
        string sectionId = enrollment.sectionId; // section this enrollment held
        if (enrollment.status == "WAITLISTED") {   // simple case: just dequeue
            auto& queue = waitlists[sectionId];
            queue.erase(remove(queue.begin(), queue.end(), enrollmentId), queue.end()); // remove from queue
            enrollment.status = "DROPPED";                                                // mark dropped
            for (auto& obs : observers) obs->onEnrollmentDropped(enrollment); // notify
            return;
        }
        enrollment.status = "DROPPED"; // mark dropped (frees a seat implicitly via confirmedCount)
        for (auto& obs : observers) obs->onEnrollmentDropped(enrollment); // notify
        auto& queue = waitlists[sectionId]; // this section's waitlist
        if (!queue.empty()) {                  // someone is waiting
            string promotedId = queue.front();   // longest-waiting entry
            queue.erase(queue.begin());            // dequeue it
            Enrollment& promoted = enrollments.at(promotedId);
            promoted.status = "CONFIRMED";           // confirmed into the freed seat
            for (auto& obs : observers) obs->onWaitlistPromoted(promoted); // notify
        }
    }
};

