class CourseRegistrationService {
    private final Map<String, Course> courses = new HashMap<>();
    private final Map<String, Section> sections = new HashMap<>();
    private final Map<String, Student> students = new HashMap<>();
    private final Map<String, Enrollment> enrollments = new HashMap<>();
    private final Map<String, List<Enrollment>> waitlists = new HashMap<>();
    private final EnrollmentEligibilityStrategy eligibilityStrategy;
    private final List<EnrollmentObserver> observers = new ArrayList<>();
    private int enrollmentCounter = 0;

    public CourseRegistrationService(EnrollmentEligibilityStrategy eligibilityStrategy) {
        this.eligibilityStrategy = eligibilityStrategy;
    }

    public void addCourse(Course course) { courses.put(course.getCourseId(), course); }
    public void addSection(Section section) {
        sections.put(section.getSectionId(), section);
        waitlists.put(section.getSectionId(), new ArrayList<>());
    }
    public void addStudent(Student student) { students.put(student.getStudentId(), student); }
    public void addObserver(EnrollmentObserver observer) { observers.add(observer); }
    public void markCourseCompleted(String studentId, String courseId) { students.get(studentId).markCompleted(courseId); }

    private List<Section> currentSectionsFor(String studentId) {
        List<Section> result = new ArrayList<>();
        for (Enrollment e : enrollments.values()) {
            if (e.getStudentId().equals(studentId) && "CONFIRMED".equals(e.getStatus())) {
                result.add(sections.get(e.getSectionId()));
            }
        }
        return result;
    }

    private int confirmedCount(String sectionId) {
        int count = 0;
        for (Enrollment e : enrollments.values()) {
            if (e.getSectionId().equals(sectionId) && "CONFIRMED".equals(e.getStatus())) count++;
        }
        return count;
    }

    public synchronized Enrollment enroll(String studentId, String sectionId) {
        Student student = students.get(studentId);
        Section section = sections.get(sectionId);
        Course course = courses.get(section.getCourseId());
        List<Section> currentSections = currentSectionsFor(studentId);
        String reason = eligibilityStrategy.checkEligibility(student, course, section, currentSections);
        enrollmentCounter++;
        String enrollmentId = "ENR-" + enrollmentCounter;
        if (reason != null) {
            for (EnrollmentObserver obs : observers) obs.onEnrollmentRejected(studentId, reason);
            throw new EnrollmentNotEligibleException(reason);
        }
        Enrollment enrollment = new Enrollment(enrollmentId, studentId, sectionId);
        if (confirmedCount(sectionId) < section.getCapacity()) {
            enrollment.setStatus("CONFIRMED");
            enrollments.put(enrollmentId, enrollment);
            for (EnrollmentObserver obs : observers) obs.onEnrollmentConfirmed(enrollment);
            return enrollment;
        }
        enrollment.setStatus("WAITLISTED");
        enrollments.put(enrollmentId, enrollment);
        waitlists.get(sectionId).add(enrollment);
        for (EnrollmentObserver obs : observers) obs.onWaitlisted(enrollment);
        return enrollment;
    }

    public synchronized void dropEnrollment(String enrollmentId) {
        Enrollment enrollment = enrollments.get(enrollmentId);
        if (enrollment == null || "DROPPED".equals(enrollment.getStatus())) {
            throw new InvalidEnrollmentException("Unknown or already-dropped enrollment: " + enrollmentId);
        }
        String sectionId = enrollment.getSectionId();
        if ("WAITLISTED".equals(enrollment.getStatus())) {
            waitlists.get(sectionId).remove(enrollment);
            enrollment.setStatus("DROPPED");
            for (EnrollmentObserver obs : observers) obs.onEnrollmentDropped(enrollment);
            return;
        }
        enrollment.setStatus("DROPPED");
        for (EnrollmentObserver obs : observers) obs.onEnrollmentDropped(enrollment);
        List<Enrollment> queue = waitlists.get(sectionId);
        if (!queue.isEmpty()) {
            Enrollment promoted = queue.remove(0);
            promoted.setStatus("CONFIRMED");
            for (EnrollmentObserver obs : observers) obs.onWaitlistPromoted(promoted);
        }
    }
}

