        enrollment.status = "WAITLISTED";
        enrollments.insert({enrollmentId, enrollment});
        waitlists[sectionId].push_back(enrollmentId);
        for (auto& obs : observers) obs->onWaitlisted(enrollment);
        return enrollment;
    }

    void dropEnrollment(string enrollmentId) {
        auto it = enrollments.find(enrollmentId);
        if (it == enrollments.end() || it->second.status == "DROPPED") {
            throw InvalidEnrollmentException("Unknown or already-dropped enrollment: " + enrollmentId);
        }
        Enrollment& enrollment = it->second;
        string sectionId = enrollment.sectionId;
        if (enrollment.status == "WAITLISTED") {
            auto& queue = waitlists[sectionId];
            queue.erase(remove(queue.begin(), queue.end(), enrollmentId), queue.end());
            enrollment.status = "DROPPED";
            for (auto& obs : observers) obs->onEnrollmentDropped(enrollment);
            return;
        }
        enrollment.status = "DROPPED";
        for (auto& obs : observers) obs->onEnrollmentDropped(enrollment);
        auto& queue = waitlists[sectionId];
        if (!queue.empty()) {
            string promotedId = queue.front();
            queue.erase(queue.begin());
            Enrollment& promoted = enrollments.at(promotedId);
            promoted.status = "CONFIRMED";
            for (auto& obs : observers) obs->onWaitlistPromoted(promoted);
        }
    }
};

